#!/usr/bin/env bash
# Build and run the unit tests. These need no real game data (data/ is not in the repo): they run
# against a synthetic data tree generated by tests/tools/make_synthetic_data.py, so CI can run them.
#
#   ./run-unit-tests.sh               unit tests (synthetic data)
#   ./run-unit-tests.sh --integration integration tests: whole suites against the real data/ folder
#   ./run-unit-tests.sh --reclassify  regenerate tests/unit-cases.txt (which cases are data-free)
#
# BUILD_DIR overrides the build directory (default: build-tests, or build-integration for
# --integration).
set -euo pipefail

PROJECT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
mode="${1:-unit}"

configure_and_build() {  # $1 build dir, $2 data dir
  cmake -S "$PROJECT_DIR" -B "$1" -DBUILD_TESTING=ON -DUW_TEST_DATA_DIR="$2"
  cmake --build "$1" --target unit_tests --parallel
}

make_synthetic() {  # $1 build dir
  rm -rf "$1/synthetic-data"
  python3 "$PROJECT_DIR/tests/tools/make_synthetic_data.py" "$1/synthetic-data"
}

case "$mode" in
  unit|--unit)
    BUILD_DIR="${BUILD_DIR:-$PROJECT_DIR/build-tests}"
    make_synthetic "$BUILD_DIR"
    configure_and_build "$BUILD_DIR" "$BUILD_DIR/synthetic-data"
    ctest --test-dir "$BUILD_DIR" -L unit --output-on-failure --parallel 4 --no-tests=error
    ;;
  --integration)
    [ -f "$PROJECT_DIR/data/UU.exe" ] || { echo "no real game data in $PROJECT_DIR/data" >&2; exit 1; }
    BUILD_DIR="${BUILD_DIR:-$PROJECT_DIR/build-integration}"
    configure_and_build "$BUILD_DIR" "$PROJECT_DIR/data"
    ctest --test-dir "$BUILD_DIR" -L integration --output-on-failure --parallel 4 --no-tests=error
    ;;
  --reclassify)
    BUILD_DIR="${BUILD_DIR:-$PROJECT_DIR/build-tests}"
    make_synthetic "$BUILD_DIR"
    configure_and_build "$BUILD_DIR" "$BUILD_DIR/synthetic-data"
    # Hide any real data so nothing can silently fall back to it.
    python3 "$PROJECT_DIR/tests/tools/classify_cases.py" "$BUILD_DIR"
    ;;
  *)
    echo "usage: $0 [--unit|--integration|--reclassify]" >&2
    exit 2
    ;;
esac
